using System.Buffers.Binary;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Microsoft.AspNetCore.DataProtection;
using Npgsql;

public record InstallationInput(string CentralUrl,string SqlServer="localhost",string SqlUsername="sa",string? SqlPassword=null,bool TrustServerCertificate=false,string SqlServiceIdentity="",string BackupDirectory="");
public record SqlRuntimeSettings(string Server,string Username,string Password,bool TrustServerCertificate,string Revision);
public record EnrollmentInput(string EnrollmentKey,Guid InstanceId,string MachineName,string? ExistingAgentToken=null);
public sealed class InstallationService(NpgsqlDataSource source,IDataProtectionProvider protection,IConfiguration configuration)
{
    readonly IDataProtector protector=protection.CreateProtector("BackupControl.Installation.v1");
    static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web);
    public string Distribution=>configuration["INSTALLER_DISTRIBUTION_DIR"]??"/app/distribution";
    public string Template=>Path.Combine(Distribution,"BackupControl.Setup.exe");
    public string Package=>Path.Combine(Distribution,"backup-control-agent-win-x64.zip");
    public string? SnapshotPath(string digest)=>digest.Length==64&&digest.All(c=>c is >= '0' and <= '9' or >= 'a' and <= 'f')?Path.Combine(Distribution,"packages",digest+".zip"):null;
 internal async Task<string?> CurrentDigest(){if(!File.Exists(Package))return null;await using var stream=File.OpenRead(Package);var digest=Convert.ToHexString(await SHA256.HashDataAsync(stream)).ToLowerInvariant();return File.Exists(SnapshotPath(digest))?digest:null;}
 static string Hash(string value)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value)));
    static string Token()=>Convert.ToHexString(RandomNumberGenerator.GetBytes(32)).ToLowerInvariant();
    public static string Origin(string value){if(!Uri.TryCreate(value,UriKind.Absolute,out var uri)||uri.Scheme!="https"||uri.UserInfo!=""||uri.AbsolutePath!="/"||uri.Query!=""||uri.Fragment!="")throw new ArgumentException("Informe a origem HTTPS da central, sem caminho, consulta ou credenciais.");return uri.GetLeftPart(UriPartial.Authority);}
    internal async Task<InstallationInput?> Settings(NpgsqlConnection? connection=null){await using var c=connection is null?source.CreateCommand("SELECT payload FROM installation_settings WHERE id=1"):Cmd(connection,"SELECT payload FROM installation_settings WHERE id=1");var value=await c.ExecuteScalarAsync();return value is string s?JsonSerializer.Deserialize<InstallationInput>(protector.Unprotect(s),Json):null;}
    public async Task<IResult> Get(){var s=await Settings();return Results.Ok(new{centralUrl=s?.CentralUrl??"",sqlServer=s?.SqlServer??"localhost",sqlUsername=s?.SqlUsername??"sa",hasSqlPassword=!string.IsNullOrEmpty(s?.SqlPassword),trustServerCertificate=s?.TrustServerCertificate??false,sqlServiceIdentity=s?.SqlServiceIdentity??"",backupDirectory=s?.BackupDirectory??"",installerAvailable=File.Exists(Template),agentPackageAvailable=await CurrentDigest() is not null});}
    public async Task<SqlRuntimeSettings?> RuntimeSql()
    {
        await using var c=source.CreateCommand("SELECT payload,sql_revision FROM installation_settings WHERE id=1");
        await using var reader=await c.ExecuteReaderAsync();if(!await reader.ReadAsync())return null;
        var s=JsonSerializer.Deserialize<InstallationInput>(protector.Unprotect(reader.GetString(0)),Json);
        return string.IsNullOrEmpty(s?.SqlPassword)?null:new(s.SqlServer,s.SqlUsername,s.SqlPassword,s.TrustServerCertificate,reader.GetGuid(1).ToString());
    }
    public async Task<IResult> Save(InstallationInput s)
    {
        s=s with{CentralUrl=Origin(s.CentralUrl)};
        if(string.IsNullOrWhiteSpace(s.SqlServer)||s.SqlServer.Length>256||string.IsNullOrWhiteSpace(s.SqlUsername)||s.SqlUsername.Length>128||s.SqlPassword?.Length>4096||s.SqlServiceIdentity?.Length>256||s.BackupDirectory?.Length>1024)throw new ArgumentException("Configuração SQL inválida.");
        await using var connection=await source.OpenConnectionAsync();await using var tx=await connection.BeginTransactionAsync();
        await Cmd(connection,"SELECT pg_advisory_xact_lock(726394812)").ExecuteNonQueryAsync();var old=await Settings(connection);
        if(string.IsNullOrEmpty(s.SqlPassword))s=s with{SqlPassword=old?.SqlPassword};
        var changed=old is null||old.SqlServer!=s.SqlServer||old.SqlUsername!=s.SqlUsername||old.SqlPassword!=s.SqlPassword||old.TrustServerCertificate!=s.TrustServerCertificate;
        await Cmd(connection,"INSERT INTO installation_settings(id,payload,sql_revision) VALUES(1,$1,$2) ON CONFLICT(id) DO UPDATE SET payload=excluded.payload,sql_revision=CASE WHEN $3 THEN excluded.sql_revision ELSE installation_settings.sql_revision END",protector.Protect(JsonSerializer.Serialize(s,Json)),Guid.NewGuid(),changed).ExecuteNonQueryAsync();
        await Cmd(connection,"INSERT INTO audit(action,detail) VALUES('installation.settings.updated','shared defaults')").ExecuteNonQueryAsync();await tx.CommitAsync();return Results.NoContent();
    }
    static NpgsqlCommand Cmd(NpgsqlConnection c,string sql,params object?[] args){var cmd=new NpgsqlCommand(sql,c);foreach(var arg in args)cmd.Parameters.Add(new NpgsqlParameter{Value=arg??DBNull.Value});return cmd;}
    public async Task<IResult> Issue(Guid id){var s=await Settings();if(string.IsNullOrEmpty(s?.SqlPassword))return Results.Conflict(new{error="Salve a senha SQL e a URL da central em Configuração de instalação."});if(!File.Exists(Template)||await CurrentDigest() is null)return Results.Json(new{error="Instalador ou pacote do agente indisponível."},statusCode:503);await using var connection=await source.OpenConnectionAsync();await using var tx=await connection.BeginTransactionAsync();await using var q=Cmd(connection,"SELECT name,enabled FROM clients WHERE id=$1 FOR UPDATE",id);string name;await using(var r=await q.ExecuteReaderAsync()){if(!await r.ReadAsync())return Results.NotFound();name=r.GetString(0);if(!r.GetBoolean(1))return Results.Conflict(new{error="Cliente pausado."});}var key=Token();var eid=Guid.NewGuid();var expiry=DateTime.UtcNow.AddHours(24);await Cmd(connection,"INSERT INTO installer_enrollments(id,client_id,key_hash,protected_key,central_url,expires_at) VALUES($1,$2,$3,$4,$5,$6)",eid,id,Hash(key),protector.Protect(key),s.CentralUrl,expiry).ExecuteNonQueryAsync();await Cmd(connection,"INSERT INTO audit(action,detail) VALUES('installer.issued',$1)",id+":"+eid).ExecuteNonQueryAsync();await tx.CommitAsync();return Results.Ok(new{id=eid,clientId=id,clientName=name,expiresAt=expiry,downloadUrl=$"/api/clients/{id}/installers/{eid}/download"});}
    public async Task<IResult> Revoke(Guid id,Guid eid){await using var connection=await source.OpenConnectionAsync();await using var tx=await connection.BeginTransactionAsync();if(await Cmd(connection,"UPDATE installer_enrollments SET revoked=true WHERE id=$1 AND client_id=$2 RETURNING id",eid,id).ExecuteScalarAsync() is null)return Results.NotFound();await Cmd(connection,"INSERT INTO audit(action,detail) VALUES('installer.revoked',$1)",id+":"+eid).ExecuteNonQueryAsync();await tx.CommitAsync();return Results.NoContent();}
    public async Task Download(Guid id,Guid eid,HttpContext ctx){await using var connection=await source.OpenConnectionAsync();await using var c=Cmd(connection,"SELECT e.protected_key,e.central_url,c.name,e.revoked OR e.expires_at<=now(),c.enabled FROM installer_enrollments e JOIN clients c ON c.id=e.client_id WHERE e.id=$1 AND e.client_id=$2",eid,id);byte[] payload;await using(var r=await c.ExecuteReaderAsync()){if(!await r.ReadAsync()){ctx.Response.StatusCode=404;return;}if(r.GetBoolean(3)||!r.GetBoolean(4)){ctx.Response.StatusCode=410;return;}payload=JsonSerializer.SerializeToUtf8Bytes(new{centralUrl=r.GetString(1),enrollmentKey=protector.Unprotect(r.GetString(0)),clientId=id,clientName=r.GetString(2)},Json);}await c.DisposeAsync();await connection.DisposeAsync();if(!File.Exists(Template)){ctx.Response.StatusCode=503;return;}await using var file=File.OpenRead(Template);ctx.Response.ContentType="application/octet-stream";ctx.Response.Headers.ContentDisposition="attachment; filename=BackupControl.Setup.exe";ctx.Response.Headers.CacheControl="no-store";ctx.Response.ContentLength=file.Length+payload.Length+16;await file.CopyToAsync(ctx.Response.Body,ctx.RequestAborted);await ctx.Response.Body.WriteAsync(payload,ctx.RequestAborted);var length=new byte[8];BinaryPrimitives.WriteInt64LittleEndian(length,payload.Length);await ctx.Response.Body.WriteAsync(length,ctx.RequestAborted);await ctx.Response.Body.WriteAsync("BCSETUP1"u8.ToArray(),ctx.RequestAborted);}
    public async Task<IResult> Redeem(EnrollmentInput input,HttpContext ctx){ctx.Response.Headers.CacheControl="no-store";if(input.InstanceId==Guid.Empty||string.IsNullOrWhiteSpace(input.MachineName)||input.MachineName.Length>120||input.EnrollmentKey is null||input.EnrollmentKey.Length!=64||!input.EnrollmentKey.All(Uri.IsHexDigit))return Results.BadRequest(new{error="Inscrição inválida."});await using var connection=await source.OpenConnectionAsync();await using var tx=await connection.BeginTransactionAsync();var cid=await Cmd(connection,"SELECT client_id FROM installer_enrollments WHERE key_hash=$1",Hash(input.EnrollmentKey)).ExecuteScalarAsync();if(cid is not Guid id)return Results.Unauthorized();string name,currentHash;Guid? bound;await using(var r=await Cmd(connection,"SELECT name,token_hash,agent_instance_id,enabled FROM clients WHERE id=$1 FOR UPDATE",id).ExecuteReaderAsync()){if(!await r.ReadAsync()||!r.GetBoolean(3))return Results.Unauthorized();name=r.GetString(0);currentHash=r.GetString(1);bound=r.IsDBNull(2)?null:r.GetGuid(2);}string origin;string? reply,tokenHash;Guid? redeemed;await using(var r=await Cmd(connection,"SELECT central_url,protected_reply,redeemed_instance_id,redeemed_token_hash,revoked OR expires_at<=now() FROM installer_enrollments WHERE key_hash=$1 FOR UPDATE",Hash(input.EnrollmentKey)).ExecuteReaderAsync()){if(!await r.ReadAsync()||r.GetBoolean(4))return Results.Unauthorized();origin=r.GetString(0);reply=r.IsDBNull(1)?null:r.GetString(1);redeemed=r.IsDBNull(2)?null:r.GetGuid(2);tokenHash=r.IsDBNull(3)?null:r.GetString(3);}if(bound.HasValue&&bound!=input.InstanceId||redeemed.HasValue&&redeemed!=input.InstanceId)return Results.Conflict(new{error="Cliente vinculado a outra instalação."});if(reply is not null){if(tokenHash!=currentHash)return Results.Conflict(new{error="Inscrição substituída. Gere um novo instalador."});await tx.CommitAsync();return Results.Text(protector.Unprotect(reply),"application/json");}if(input.ExistingAgentToken is not null && (!bound.HasValue || input.ExistingAgentToken.Length>200 || !CryptographicOperations.FixedTimeEquals(Encoding.ASCII.GetBytes(Hash(input.ExistingAgentToken)),Encoding.ASCII.GetBytes(currentHash))))return Results.Conflict(new{error="Token operacional de reparo inválido."});var s=await Settings(connection);var digest=await CurrentDigest();if(string.IsNullOrEmpty(s?.SqlPassword)||digest is null)return Results.Json(new{error="Configuração ou pacote indisponível."},statusCode:503);var token=input.ExistingAgentToken??Token();var json=JsonSerializer.Serialize(new{clientId=id,clientName=name,centralUrl=origin,agentToken=token,sql=new{server=s.SqlServer,username=s.SqlUsername,password=s.SqlPassword,trustServerCertificate=s.TrustServerCertificate,serviceIdentity=s.SqlServiceIdentity,backupDirectory=s.BackupDirectory},package=new{url=origin+"/api/agent/package/"+digest,sha256=digest}},Json);await Cmd(connection,"UPDATE clients SET token_hash=$2,agent_instance_id=$3,machine_name=$4 WHERE id=$1",id,Hash(token),input.InstanceId,input.MachineName).ExecuteNonQueryAsync();await Cmd(connection,"UPDATE installer_enrollments SET protected_reply=$2,redeemed_instance_id=$3,redeemed_token_hash=$4,redeemed_at=now() WHERE key_hash=$1",Hash(input.EnrollmentKey),protector.Protect(json),input.InstanceId,Hash(token)).ExecuteNonQueryAsync();await tx.CommitAsync();return Results.Text(json,"application/json");}
}


